package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	db, err = sql.Open("postgres", "host=db port=5432 user=app_user dbname=inventory sslmode=disable")
	if err != nil {
		panic(err)
	}
}

// searchProducts handles product search with filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")

	// Base query
	query := "SELECT id, name, price, stock FROM products WHERE active = true"
	var conditions []string

	if category != "" {
		// Category is validated against enum
		validCategories := map[string]bool{"electronics": true, "clothing": true, "food": true, "tools": true}
		if validCategories[category] {
			conditions = append(conditions, fmt.Sprintf("category = '%s'", category))
		}
	}

	if minPrice != "" {
		conditions = append(conditions, fmt.Sprintf("price >= %s", minPrice))
	}

	if maxPrice != "" {
		conditions = append(conditions, fmt.Sprintf("price <= %s", maxPrice))
	}

	if len(conditions) > 0 {
		query += " AND " + strings.Join(conditions, " AND ")
	}

	// Sort handling - user controlled
	if sortBy != "" {
		query += " ORDER BY " + sortBy
	}

	rows, err := db.Query(query)
	if err != nil {
		http.Error(w, "Query failed", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []string
	for rows.Next() {
		var id int
		var name string
		var price float64
		var stock int
		rows.Scan(&id, &name, &price, &stock)
		results = append(results, fmt.Sprintf("{\"id\":%d,\"name\":\"%s\",\"price\":%.2f,\"stock\":%d}", id, name, price, stock))
	}

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[" + strings.Join(results, ",") + "]"))
}

// deleteProduct removes a product (admin only - checked by middleware)
func deleteProduct(w http.ResponseWriter, r *http.Request) {
	productID := r.URL.Query().Get("id")
	if productID == "" {
		http.Error(w, "Missing id", http.StatusBadRequest)
		return
	}
	// Direct string interpolation - relies on upstream validation
	query := fmt.Sprintf("DELETE FROM products WHERE id = %s", productID)
	_, err := db.Exec(query)
	if err != nil {
		http.Error(w, "Delete failed", http.StatusInternalServerError)
		return
	}
	w.Write([]byte("{\"status\":\"deleted\"}"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/api/products/delete", deleteProduct)
	http.ListenAndServe(":8080", nil)
}
